import React from 'react';
import { useParams, Link } from 'react-router-dom';

const CursoDetalle = () => {
  const { id } = useParams();

  const curso = {
    id,
    nombre: id === '1' ? 'Curso de React' : 'Curso de JavaScript',
    descripcion: id === '1' ? 'Aprende a desarrollar aplicaciones web con React.' : 'Domina el lenguaje de programación JavaScript.'
  };

  return (
    <div className="curso-detalle">
      <h1>{curso.nombre}</h1>
      <p>{curso.descripcion}</p>
      <Link to={`/inscripcion/${curso.id}`}>Inscribirse</Link>
    </div>
  );
};

export default CursoDetalle;
